        # it: a step missing any one of them is a step whose ordering nothing can
        # perform, and the key the refusal names is the only thing that tells an
        # adopter which.
        ("a step with no backup", "deploy[0].live_data_step.backup",
         at("deploy", [_a_deploy_target(live_data_step=_a_live_data_step(backup=_ABSENT))])),
        ("a step with nothing to apply", "deploy[0].live_data_step.apply",
         at("deploy", [_a_deploy_target(live_data_step=_a_live_data_step(apply=_ABSENT))])),
        ("a step saying nothing about who performs the write",
         "deploy[0].live_data_step.apply_by",
         at("deploy", [_a_deploy_target(live_data_step=_a_live_data_step(apply_by=_ABSENT))])),
        ("a step saying nothing about which side of the invocation it falls on",
         "deploy[0].live_data_step.order",
         at("deploy", [_a_deploy_target(live_data_step=_a_live_data_step(order=_ABSENT))])),
        ("a step saying nothing about what the store already holds",
         "deploy[0].live_data_step.record",
         at("deploy", [_a_deploy_target(live_data_step=_a_live_data_step(record=_ABSENT))])),
        ("a backup that is not a block", "deploy[0].live_data_step.backup",
         at("deploy", [_a_deploy_target(
             live_data_step=_a_live_data_step(backup="a-dump"))])),
        ("a key § 35 declares on no backup", "deploy[0].live_data_step.backup.retain",
         at("deploy", [_a_deploy_target(live_data_step=_a_live_data_step(
             backup={"run": "a-dump", "verify": "a-read-back", "retain": "a week"}))])),
        # ⛔ Both halves of the backup, which is the pair § 35 makes two keys for:
        # a dump that failed still leaves a file, so the dump alone says nothing.
        ("a backup with no dump to take", "deploy[0].live_data_step.backup.run",
         at("deploy", [_a_deploy_target(live_data_step=_a_live_data_step(
             backup={"verify": "a-read-back"}))])),
        ("a backup nothing reads back", "deploy[0].live_data_step.backup.verify",
         at("deploy", [_a_deploy_target(live_data_step=_a_live_data_step(
             backup={"run": "a-dump"}))])),
        ("a dump command written blank", "deploy[0].live_data_step.backup.run",
         at("deploy", [_a_deploy_target(live_data_step=_a_live_data_step(
             backup={"run": "   ", "verify": "a-read-back"}))])),
        ("a verification written blank", "deploy[0].live_data_step.backup.verify",
         at("deploy", [_a_deploy_target(live_data_step=_a_live_data_step(
             backup={"run": "a-dump", "verify": "   "}))])),
        ("an apply written blank", "deploy[0].live_data_step.apply",
         at("deploy", [_a_deploy_target(live_data_step=_a_live_data_step(apply="   "))])),
        ("a rehearsal written blank", "deploy[0].live_data_step.rehearse",
         at("deploy", [_a_deploy_target(live_data_step=_a_live_data_step(rehearse="   "))])),
        ("a record command written blank", "deploy[0].live_data_step.record",
         at("deploy", [_a_deploy_target(live_data_step=_a_live_data_step(record="   "))])),
        ("who performs the write, outside its alternation",
         "deploy[0].live_data_step.apply_by",
         at("deploy", [_a_deploy_target(
             live_data_step=_a_live_data_step(apply_by="whoever-is-around"))])),
        ("an order outside its alternation", "deploy[0].live_data_step.order",
         at("deploy", [_a_deploy_target(
             live_data_step=_a_live_data_step(order="whenever"))])),
        # ⛔ The three shapes an answer is fed by, each planted alone, and the
        # false-refusal bound beside them in the green side below. ⚠️ The pipe is
        # planted on both of the commands this rule reaches, since a rule written
        # for one of them would leave the dry variant able to clear its own prompt
        # — and a cleared rehearsal is a rehearsal whose reading was never owed.
        ("an apply that pipes itself an answer", "deploy[0].live_data_step.apply",
         at("deploy", [_a_deploy_target(live_data_step=_a_live_data_step(
             apply="echo y | a-write"))])),
        ("an apply that answers itself with a here-string",
         "deploy[0].live_data_step.apply",
         at("deploy", [_a_deploy_target(live_data_step=_a_live_data_step(
             apply="a-write <<< y"))])),
        ("a rehearsal that pipes itself an answer", "deploy[0].live_data_step.rehearse",
         at("deploy", [_a_deploy_target(live_data_step=_a_live_data_step(
             rehearse="yes | a-dry-run"))])),
        ("an answer fed by a printing command behind an assignment",
         "deploy[0].live_data_step.apply",
         at("deploy", [_a_deploy_target(live_data_step=_a_live_data_step(
             apply="STORE=a-url printf 'y\\n' | a-write"))])),
        # § 34's shape, one plant per arm. ⛔ Every one of them replaces the whole
        # facet rather than editing the base example's, which is this list's rule
        # for `_a_deploy_target` read one facet over: a plant that broke one key
        # of a shipped file would stop asserting the moment that file's list grew
        # a second entry, and the half of it that is a *plant* would be invisible.
        #
        # ⛔ The first is the arm the carrier's own alternation cannot reach: a
        # project that states it cuts no release and then states the list anyway.
        # The marker makes the list required under `list` and says nothing about
        # the other direction, which would leave a release configured and nothing
        # performing it.
        ("a file list stated beside a carrier that reads none", "release.files",
         at("release", {"carrier": "none", "absent_reason": "nothing is versioned",
                        "files": [_a_release_file()]})),
        ("a file list that is not a list", "release.files",
         at("release", _a_release_of(files="a-build-file"))),
        # ⚠️ The empty list is its own arm and not a spelling of the one above:
        # § 34 makes `carrier: none` the way a project says no file carries a
        # version, so `[]` is a project that cuts releases and has not found its
        # files -- which must not read as the stated absence.
        ("a file list carrying no file", "release.files",
         at("release", _a_release_of(files=[]))),
        ("a file entry that is not a block", "release.files[0]",
         at("release", _a_release_of(files=["a-build-file"]))),
        ("a key § 34 declares on no file", "release.files[0].encoding",
         at("release", _a_release_of(
             files=[_a_release_file(encoding="a fact about the file nothing reads")]))),
        ("a file with no path", "release.files[0].path",
         at("release", _a_release_of(files=[_a_release_file(path=_ABSENT)]))),
        ("a path written blank", "release.files[0].path",
         at("release", _a_release_of(files=[_a_release_file(path="   ")]))),
        # ⛔ Two entries over one file, which is the arm about the list rather
        # than about an entry: the second edit reads the first one's output
        # instead of the file the project described.
        ("one path edited twice", "release.files[1].path",
         at("release", _a_release_of(
             files=[_a_release_file(), _a_release_file()]))),
        ("a file with no kind of edit", "release.files[0].kind",
         at("release", _a_release_of(files=[_a_release_file(kind=_ABSENT)]))),
        ("a kind outside its alternation", "release.files[0].kind",
         at("release", _a_release_of(files=[_a_release_file(kind="rewrite")]))),
        # ⛔ Both directions of every per-kind key, which is § 33's rule for the
        # same shape: one the kind needs and the entry leaves out, one the entry
        # states and the kind never reads. ⚠️ The second is the one a reader is
        # tempted to tolerate, and tolerating it leaves a `pattern` beside a
        # changelog -- a fact written exactly where somebody expects it read.
        ("a regex file with no pattern", "release.files[0].pattern",
         at("release", _a_release_of(files=[_a_release_file(pattern=_ABSENT)]))),
        ("a regex file with no replacement", "release.files[0].replace",
         at("release", _a_release_of(files=[_a_release_file(replace=_ABSENT)]))),
        ("a pattern stated beside a changelog", "release.files[0].pattern",
         at("release", _a_release_of(files=[_a_release_file(
             kind="changelog", replace=_ABSENT)]))),
        ("a replacement stated beside a changelog", "release.files[0].replace",
         at("release", _a_release_of(files=[_a_release_file(
             kind="changelog", pattern=_ABSENT)]))),
        ("a pattern written blank", "release.files[0].pattern",
         at("release", _a_release_of(files=[_a_release_file(pattern="   ")]))),
        ("a replacement written blank", "release.files[0].replace",
         at("release", _a_release_of(files=[_a_release_file(replace="   ")]))),
        # ⛔ Compiled at the load, so an expression no engine can parse is refused
        # where it is written rather than at the first file of a release that has
        # already spent a version.
        ("a pattern no engine can compile", "release.files[0].pattern",
         at("release", _a_release_of(files=[_a_release_file(pattern="v(")]))),
        # ⛔ And the capture, which is the only thing the role learns about a
        # project's scheme. ⚠️ Planted on a pattern that **matches** the version
        # without capturing it: a pattern matching nothing at all is a stop the
        # carrier takes against the file, which says nothing about this arm.
        ("a pattern matching the version without capturing it",
         "release.files[0].pattern",
         at("release", _a_release_of(files=[_a_release_file(pattern=r"v\d+")]))),
        # ⛔ The pair § 34 refuses at the load: a project asking for the changelog
        # to be written and declaring that it may not be.
        ("a changelog entry beside a changelog CI owns", "release.files[0].kind",
         at("release", _a_release_of(
             changelog_ci_owned=True,
             files=[_a_release_file(kind="changelog", pattern=_ABSENT,
                                    replace=_ABSENT)]))),
        # ⛔ Read for neither truth nor presence, which is § 1's rule for
        # `code_root_runs_nothing` arriving at the three booleans this facet has.
        # ⚠️ Each is planted as a word a truthy read would accept, that being the
        # reading which fails silently.
        ("a file's optionality written as a word rather than a boolean",
         "release.files[0].optional",
         at("release", _a_release_of(files=[_a_release_file(optional="yes")]))),
        ("publishing written as a word rather than a boolean",
         "release.publishes_packages",
         at("release", _a_release_of(publishes_packages="yes"))),
        ("the changelog's ownership written as a word rather than a boolean",
         "release.changelog_ci_owned",
         at("release", _a_release_of(changelog_ci_owned="yes"))),
        # § 37, and the arms no marker reaches. ⛔ Every one of them fails in the
        # same direction if it is not held: a root that is dropped, read twice or
        # resolved against the wrong directory changes what somebody is billed,
        # and nothing downstream of this reader can see which of those happened.
        #
        # ⚠️ The complement first, which is § 34's own arm one facet over: a key
        # stated beside a carrier that reads none is a period somebody
        # configured and nothing assembles.
        ("a root list stated beside a carrier that reads none", "billing.projects",
         at("billing", {"carrier": "none", "absent_reason": "nobody is billed",
                        "projects": ["/a-project"]})),
        ("a rate stated beside a carrier that reads none", "billing.rates",
         at("billing", {"carrier": "none", "absent_reason": "nobody is billed",
                        "rates": {"a-client": 1}})),
        ("a root list that is not a list", "billing.projects",
         at("billing", _a_billing_of(projects="/a-project"))),
        # ⚠️ The empty list is its own arm and not a spelling of the one above,
        # which is § 34's reason for the same pair: `carrier: none` is how § 37
        # says nobody is billed, so `[]` is a project that bills somebody from no
        # project at all and must not read as the stated absence.
        ("a root list naming no project", "billing.projects",
         at("billing", _a_billing_of(projects=[]))),
        ("a root that is not a path", "billing.projects[0]",
         at("billing", _a_billing_of(projects=[{"root": "/a-project"}]))),
        ("a root written blank", "billing.projects[0]",
         at("billing", _a_billing_of(projects=["   "]))),
        # ⛔ The arm § 37 states in prose because no marker can: a relative root
        # resolves against whatever directory the role stands in, and under § 10
        # that is a different tree per item -- so one configuration would
        # assemble a period from a different set of projects per call.
        ("a root written relatively", "billing.projects[0]",
         at("billing", _a_billing_of(projects=["../a-sibling-project"]))),
        ("a root the list already names", "billing.projects[1]",
         at("billing", _a_billing_of(projects=["/a-project", "/a-project"]))),
        # ⛔ One plant per spelling, because the first form of the arm compared
        # the strings and all four of these were measured **accepted** -- the
        # same project read twice and billed twice. ⚠️ A single plant would
        # assert the comparison is normalised at all and not that it reaches the
        # shapes a person actually writes.
        ("a root the list already names, under a trailing separator",
         "billing.projects[1]",
         at("billing", _a_billing_of(projects=["/a-project", "/a-project/"]))),
        ("a root the list already names, under a doubled separator",
         "billing.projects[1]",
         at("billing", _a_billing_of(projects=["/a-project", "/a-project//"]))),
        ("a root the list already names, under a dot segment",
         "billing.projects[1]",
         at("billing", _a_billing_of(projects=["/a-project", "/a-project/."]))),
        ("a root the list already names, under a parent segment resolving back",
         "billing.projects[1]",
         at("billing",
            _a_billing_of(projects=["/a-project", "/a-project/sub/.."]))),
        # ⚠️ POSIX reserves exactly two leading separators and `normpath` is
        # required to preserve them, so this spelling survived the fix the four
        # above were written for and was measured **accepted**. Three or more
        # were already collapsed, which is why this is one plant and not two.
        ("a root the list already names, under a leading double separator",
         "billing.projects[1]",
         at("billing", _a_billing_of(projects=["/a-project", "//a-project"]))),
        ("a rate that is not a mapping of client to rate", "billing.rates",
         at("billing", _a_billing_of(rates="an-hourly-rate"))),
        ("a rate mapping naming no client", "billing.rates",
         at("billing", _a_billing_of(rates={}))),
        # ⛔ Both halves of an entry, each its own arm. ⚠️ Every one of these was
        # measured **accepted** while the sibling root list refused a non-string,
        # a blank, a relative path and a duplicate -- so the key whose permissive
        # reading is money was the loose one.
        ("a rate mapping naming a client that is not a word", "billing.rates",
         at("billing", _a_billing_of(rates={"   ": 100}))),
        ("a rate written null for one client", "billing.rates",
         at("billing", _a_billing_of(rates={"a-client": None}))),
        ("a rate written blank for one client", "billing.rates",
         at("billing", _a_billing_of(rates={"a-client": "  "}))),
        ("a rate written as a container for one client", "billing.rates",
         at("billing", _a_billing_of(rates={"a-client": [1]}))),
        ("a rate written as a mapping for one client", "billing.rates",
         at("billing", _a_billing_of(rates={"a-client": {"per-hour": 1}}))),
        ("a rate written at zero", "billing.rates",
         at("billing", _a_billing_of(rates={"a-client": 0}))),
        ("a rate written below zero", "billing.rates",
         at("billing", _a_billing_of(rates={"a-client": -50}))),
        # ⚠️ A boolean is its own arm because `bool` is an `int` here, so a
        # `true` would otherwise reach the sign test and pass it.
        ("a rate written as a flag", "billing.rates",
         at("billing", _a_billing_of(rates={"a-client": True}))),
        # § 38, and the arms no marker reaches. ⛔ Every one fails in the same
        # direction if it is not held: a row nobody can read is a document held
        # to nothing while the run holding it stays green, and the governed-set
        # rule one level down would then report that document as undeclared.
        #
        # ⚠️ The complement first, which is § 34's and § 37's own arm one facet
        # over: a key stated beside a carrier that reads none is a set of
        # documents somebody governed and nothing holds.
        ("a graph stated beside a carrier that reads none", "documents.graph",
         at("documents", {"carrier": "none", "absent_reason": "nothing is governed",
                          "graph": [_a_document_row()]})),
        ("a glob list stated beside a carrier that reads none", "documents.files",
         at("documents", {"carrier": "none", "absent_reason": "nothing is governed",
                          "files": ["*.md"]})),
        ("a glob list that is not a list", "documents.files",
         at("documents", _a_documents_of(files="*.md"))),
        # ⚠️ The empty list is its own arm and not a spelling of the one above,
        # which is § 34's reason for the same pair: `carrier: none` is how § 38
        # says nothing is governed, so `[]` is a project that governs documents
        # and matched none of them -- a check that never fires while reading as
        # one that does.
        ("a glob list matching nothing by construction", "documents.files",
         at("documents", _a_documents_of(files=[]))),
        ("a glob that is not a path", "documents.files[0]",
         at("documents", _a_documents_of(files=[{"glob": "*.md"}]))),
        ("a glob written blank", "documents.files[0]",
         at("documents", _a_documents_of(files=["   "]))),
        # ⛔ Absolute paths are their own arm in both lists: one names a place on
        # one machine, so the same configuration governs a different set per
        # checkout -- § 37's relative-root arm inverted, and failing the same way.
        ("a glob written absolutely", "documents.files[0]",
         at("documents", _a_documents_of(files=["/a-document.md"]))),
        ("an entry-point list carrying no document", "documents.entry_points",
         at("documents", _a_documents_of(entry_points=[]))),
        ("an entry point written absolutely", "documents.entry_points[0]",
         at("documents", _a_documents_of(entry_points=["/a-document.md"]))),
        ("a graph that is not a list", "documents.graph",
         at("documents", _a_documents_of(graph={"document": "a-document.md"}))),
        ("a graph carrying no row", "documents.graph",
         at("documents", _a_documents_of(graph=[]))),
        ("a graph row that is not a block", "documents.graph[0]",
         at("documents", _a_documents_of(graph=["a-document.md"]))),
        ("a key § 38 declares on no graph row", "documents.graph[0].audience",
         at("documents", _a_documents_of(
             graph=[_a_document_row(audience="a fact nothing reads")]))),
        ("a graph row naming no document", "documents.graph[0].document",
         at("documents", _a_documents_of(graph=[_a_document_row(document=_ABSENT)]))),
        ("a document written blank", "documents.graph[0].document",
         at("documents", _a_documents_of(graph=[_a_document_row(document="  ")]))),
        # ⚠️ Surrounding whitespace is its own arm: the value is a non-empty
        # string, so every other test passes it, and it then matches no file and
        # is reported as a document that is not there.
        ("a document carrying surrounding whitespace", "documents.graph[0].document",
         at("documents", _a_documents_of(
             graph=[_a_document_row(document=" a-document.md")]))),
        ("a document written absolutely", "documents.graph[0].document",
         at("documents", _a_documents_of(
             graph=[_a_document_row(document="/a-document.md")]))),
        # ⛔ Two rows over one document, which is the arm about the row set rather
        # than about a row: which row is enforced is then decided by their order.
        ("one document given two rows", "documents.graph[1].document",
         at("documents", _a_documents_of(
             graph=[_a_document_row(), _a_document_row()]))),
        # ⛔ An omitted edge list and an empty one are **two arms**, and the
        # omission is the one that reads like the other: `[]` is a document that
        # may name nothing at all, which is the check with teeth, so an omission
        # permitted here would turn that check off while reading as it.
        ("a graph row omitting the enforced edge", "documents.graph[0].may_name",
         at("documents", _a_documents_of(graph=[_a_document_row(may_name=_ABSENT)]))),
        # ⛔ `null` is admitted on the enforced edge and refused on the
        # derivation record, which is the asymmetry § 38 states: a project may
        # decline to enforce what a document names, and a derivation record
        # that declined to say anything would leave the completeness rule with
        # nothing to be about.
        ("a derivation record written null", "documents.graph[0].derived_from",
         at("documents", _a_documents_of(graph=[_a_document_row(derived_from=None)]))),
        # § 38's spelling, both ways it can be unusable. ⚠️ The second is the one
        # that would otherwise match nothing in silence, which reads as every
        # edge to that document having been dropped.
        ("a spelling written blank", "documents.graph[0].named_as",
         at("documents", _a_documents_of(graph=[_a_document_row(named_as="   ")]))),
        ("a spelling that is not a usable expression", "documents.graph[0].named_as",
         at("documents", _a_documents_of(graph=[_a_document_row(named_as="a(role")]))),
        ("a graph row omitting the derivation record", "documents.graph[0].derived_from",
         at("documents",
            _a_documents_of(graph=[_a_document_row(derived_from=_ABSENT)]))),
        ("an enforced edge list that is not a list", "documents.graph[0].may_name",
         at("documents",
            _a_documents_of(graph=[_a_document_row(may_name="b-document.md")]))),
        ("an edge written blank", "documents.graph[0].may_name[0]",
         at("documents", _a_documents_of(graph=[_a_document_row(may_name=["  "])]))),
        # ⛔ A document as an edge to itself, in both lists: under `derived_from`
        # it is a one-node cycle the walk would otherwise have to find, and under
        # `may_name` it is a rule every document satisfies by carrying its own
        # name.
        ("a document named as its own enforced edge", "documents.graph[0].may_name[0]",
         at("documents", _a_documents_of(
             graph=[_a_document_row(may_name=["a-document.md"])]))),
        ("a document derived from itself", "documents.graph[0].derived_from[0]",
         at("documents", _a_documents_of(
             graph=[_a_document_row(derived_from=["a-document.md"])]))),
        ("one edge stated twice", "documents.graph[0].may_name[1]",
         at("documents", _a_documents_of(graph=[
             _a_document_row(may_name=["b-document.md", "b-document.md"]),
             _a_document_row(document="b-document.md")]))),
        # ⛔ The two arms about the row set, neither of which a per-row marker
        # could ask. The first is the one that reads as covered: a row naming a
        # document the graph does not declare looks like an edge and is an edge
        # out of the graph, and the document it points at is held to nothing.
        ("an enforced edge to a document no row declares",
         "documents.graph[0].may_name[0]",
         at("documents",
            _a_documents_of(graph=[_a_document_row(may_name=["b-document.md"])]))),
        ("a derivation from a document no row declares",
         "documents.graph[0].derived_from[0]",
         at("documents",
            _a_documents_of(graph=[_a_document_row(derived_from=["b-document.md"])]))),
        ("a derivation record that runs in a circle", "documents.graph",
         at("documents", _a_documents_of(graph=[
             _a_document_row(derived_from=["b-document.md"]),
             _a_document_row(document="b-document.md",
                             derived_from=["a-document.md"])]))),
        ("a forbidding list that is not a list", "documents.forbidden",
         at("documents", _a_documents_of(forbidden="ALegacyName"))),
        ("a forbidding entry that is not a block", "documents.forbidden[0]",
         at("documents", _a_documents_of(forbidden=["ALegacyName"]))),
        ("a key § 38 declares on no forbidding entry", "documents.forbidden[0].since",
         at("documents", _a_documents_of(
             forbidden=[_a_forbidden_name(since="a fact nothing reads")]))),
        ("a forbidden pattern with no pattern", "documents.forbidden[0].pattern",
         at("documents",
            _a_documents_of(forbidden=[_a_forbidden_name(pattern=_ABSENT)]))),
        # ⛔ Both of the prose keys, each its own arm. ⚠️ `stable_because` is the
        # one a reader is tempted to tolerate, and tolerating it leaves a
        # forbidding check nobody can tell a false refusal from: § 38 makes the
        # kind sound exactly where the forbidden thing is stable, and the entry
        # is where that is stated.
        ("a forbidden pattern with no reason", "documents.forbidden[0].reason",
         at("documents",
            _a_documents_of(forbidden=[_a_forbidden_name(reason=_ABSENT)]))),
        ("a forbidden pattern with nothing stabilising it",
         "documents.forbidden[0].stable_because",
         at("documents",
            _a_documents_of(forbidden=[_a_forbidden_name(stable_because=_ABSENT)]))),
