def _an_in_place_memory_project() -> dict:
    """A project that runs the memory third and cuts no tree.

    ⛔ Built from two shipped examples rather than written here, and built at all
    because no single example is in this state: every one that runs the memory
    third cuts a tree per item, so § 25's *this key decides nothing* line would be
    a branch nothing could fail. ⚠️ Both halves are found by the value they carry
    rather than named, which is the rule `_a_valid_example` above follows.
    """
    pinned = _example_meeting(f"{MEMORY_KEY}.carrier", "path")
    in_place = _example_meeting("branch_model.kind", "in_place")
    if pinned is None or in_place is None:
        return {}
    return _with(dict(pinned), "branch_model", in_place["branch_model"])


def _refused_or_reported(data: dict) -> list[str]:
    """What `unavailable()` reports for `data`, or the one refusal it raised."""
    if not data:
        return ["no example carries the halves this fixture is built from"]
    with open(SURFACE, encoding="utf-8") as handle:
        facts = surface_facts(handle.read())
    try:
        return _resolve(data, EXAMPLES, facts, False).unavailable()
    except ConfigError as error:
        return [f"refused {error.key}"]


def _a_valid_example() -> dict:
    """Any complete example, to break in a stated way.

    Taken from the directory rather than named: a fixture that names one tracker
    is the toolkit's code naming a tracker, which is the thing the procedure
    does not do.
    """
    with open(_examples()[0], encoding="utf-8") as handle:
        return _load_yaml(handle.read(), CONFIG_PATH)


def _a_role_no_status_maps() -> str:
    """A role § 4.2 states that the example `_a_valid_example` maps no status to.

    ⛔ Derived from the surface and the example together, because a literal here
    is one rename away from sending its plant into the **vocabulary** branch
    under the same key -- which reads green while asserting nothing about the
    agreement between `reversals` and `statuses` (§ 32). ⚠️ Raises rather than
    answering where the example maps every role the surface states: there is then
    no such role to plant, and a plant built on a fallback would assert whatever
    the fallback happened to be.
    """
    mapped = {
        status.get("role")
        for status in _absent_as(_get(_a_valid_example(), "statuses"), [])
        if isinstance(status, dict)
    }
    for role in facts_for("role"):
        if role not in mapped:
            return role
    raise ConfigError(
        "statuses",
        "the example maps every role the surface states, so § 32's "
        "target-no-status-maps plant has no role to aim at and would assert "
        "nothing. Plant it against an example that maps a subset.",
    )


def _a_role_some_status_maps() -> str:
    """A role the example `_a_valid_example` **does** map a status to (§ 4.2).

    ⛔ The complement of `_a_role_no_status_maps` above, and derived for the same
    reason: § 33's batch plant needs an advance that gets **past** the
    role-no-status-maps branch, so a literal here is one example away from being
    refused by that branch instead — which reads green under the same key while
    asserting nothing about the rule it was written for.
    """
    for status in _absent_as(_get(_a_valid_example(), "statuses"), []):
        if isinstance(status, dict) and status.get("role") in facts_for("role"):
            return status["role"]
    raise ConfigError(
        "statuses",
        "the example maps no role the surface states, so § 33's batch plant has "
        "no advance to aim at and would assert nothing.",
    )


def _a_workflow_the_example_states() -> str:
    """A workflow name `_a_valid_example`'s own `host.checks` carries (§ 2).

    ⛔ Derived rather than written, for `_a_role_no_status_maps`'s reason: a
    § 33 plant aimed past the workflow-agreement branch has to carry a name that
    branch accepts, and a literal is one example away from being refused there
    instead — green under a key that says nothing about the arm planted for.
    """
    with open(SURFACE, encoding="utf-8") as handle:
        facts = surface_facts(handle.read())
    stated = sorted(_workflows_anywhere(_a_valid_example(), facts))
    if not stated:
        raise ConfigError(
            "host.checks",
            "the example states no workflow, so § 33's input plants have no name "
            "to carry past the workflow-agreement branch and would assert nothing.",
        )
    return stated[0]


def _a_choice(**overrides) -> dict:
    """One § 33 choice, minimal and correct."""
    choice = {
        "name": "scope", "values": ["some", "all"], "default": "some",
        "warnings": {"all": "slow"},
    }
    choice.update(overrides)
    if "values" in overrides and "warnings" not in overrides:
        choice.pop("warnings")
    return {key: value for key, value in choice.items() if value is not _ABSENT}


def _a_tree_condition(**overrides) -> dict:
    """One § 33 tree condition, minimal and correct."""
    condition = {"condition": "clean", "holds": "deploy"}
    condition.update(overrides)
    return {key: value for key, value in condition.items() if value is not _ABSENT}


def _a_deploy_target(**overrides) -> dict:
    """§ 33's smallest valid target, to break one key of at a time.

    ⛔ Built here rather than borrowed from whichever example carries the facet,
    for the reason every other fixture in this module is: a plant that broke one
    key of a shipped file would stop asserting the moment that file grew a
    second target, and the half of it that is a *plant* would be invisible.
    ⚠️ It states no `workflow` and no `command_root`, so no arm of it depends on
    what the example it is placed into happens to declare.
    """
    target = {
        "name": "a-target",
        "not_live": True,
        "invoke": "command",
        "command": "a-command",
        "advances": "none",
        # § 33's publishing half, in the shape that depends on nothing the example
        # it is placed into happens to carry: a grouping named here would have to
        # be one *that* project plans in, and a role named here one its own
        # `statuses` map.
        "grouping": "none",
        "requires_role": "none",
        "publishes": False,
    }
    target.update(overrides)
    return {key: value for key, value in target.items() if value is not _ABSENT}


def _a_grouping_the_example_plans_in() -> str:
    """The name a § 33 target may write for `_a_valid_example`'s own grouping.

    ⛔ Derived rather than written, for `_a_workflow_the_example_states`'s
    reason: the single form resolves to one entry under `ONE_GROUPING` and the
    collection form carries the project's own names, so a literal here would be
    refused by the form rule instead of reaching the arm it was planted for --
    green under a key saying nothing about what was asserted.

    ⛔ Raises where the example plans in no grouping, rather than answering with
    something: the green arms below would then assert nothing while still
    reading as green, which is the one shape this module may not fail in.
    """
    with open(SURFACE, encoding="utf-8") as handle:
        facts = surface_facts(handle.read())
    data = _a_valid_example()
    groupings, collection = _groupings(data, facts)
    carried = sorted(
        name for name, entry in groupings.items()
        if isinstance(entry, dict) and entry.get("carrier") not in (None, "none")
    )
    if not carried:
        raise ConfigError(
            GROUPING_KEY,
            "the example plans in no grouping, so § 33's publishing arms have no "
            "name to carry and the plants aimed at them would be refused for the "
            "absence rather than for what they plant.",
        )
    return carried[0] if collection else ONE_GROUPING


def _unscope_targets(data: dict) -> dict:
    """Every § 33 target in `data` scoped to no grouping, and publishing none.

    ⛔ For the fixtures that make § 4.8's facet absent on a shipped file: a
    target naming a grouping the project no longer plans in is refused, which is
    the facet working rather than the fixture's problem -- so the fixture writes
    what such a project writes instead of asserting around the refusal.
    """
    for entry in _absent_as(_get(data, "deploy"), []):
        if isinstance(entry, dict):
            entry[GROUPING_ENTRY_KEY] = "none"
            entry["publishes"] = False
    return data


def _unkeep_record(data: dict, *, in_grouping: str | None = None) -> dict:
    """§ 40's record moved off a grouping `data` no longer carries.

    ⛔ The same shape `_unscope_targets` has above and for the same reason: an
    order of work kept in a grouping the project has stopped planning in is
    refused, which is § 40 working rather than the fixture's problem. ⚠️ Two
    outcomes, because the honest configuration differs: where a sibling grouping
    survives, that is where such a project would keep the order -- so the record
    is **pointed at it** rather than emptied, which keeps the fixture exercising
    the carrier it was written under.
    """
    record = _absent_as(_get(data, "ordering.record"), {})
    if not isinstance(record, dict) or record.get("carrier") != "grouping":
        return data
    if in_grouping is not None:
        record[GROUPING_ENTRY_KEY] = in_grouping
        return data
    record.clear()
    record["carrier"] = "none"
    record["absent_reason"] = (
        "the grouping the order was kept in is no longer planned in here."
    )
    return data


def _a_live_data_step(**overrides) -> dict:
    """§ 35's smallest valid block, to break one key of at a time.

    ⛔ Built here rather than borrowed from whichever example carries the facet,
    for `_a_deploy_target`'s reason: a plant that broke one key of a shipped file
    would stop asserting the moment that file grew a second target.
    ⚠️ It states no `rehearse`, that being the one key § 35 lets a block omit, so
    the arms about it state it themselves and the arm about its absence is the
    fixture as it stands.
    """
    step = {
        "backup": {"run": "a-dump", "verify": "a-read-back"},
        "apply": "a-write",
        # ⛔ Read off the surface rather than spelled, for the reason
        # `_a_workflow_the_example_states` is derived: a literal here is one
        # renamed alternation member away from being refused by the vocabulary
        # arm rather than by whichever arm the plant was aimed at -- green under
        # a key that says nothing about it.
        "apply_by": _a_member_of("deploy.live_data_step.apply_by"),
        "order": _a_member_of("deploy.live_data_step.order"),
        "record": "a-listing",
    }
    step.update(overrides)
    return {key: value for key, value in step.items() if value is not _ABSENT}


def _a_member_of(path: str) -> str:
    """The surface's first stated member of one alternation.

    ⛔ Refused **with the path named** where the surface states none, rather than
    raising an index error out of the suite: the plants that carry this would
    otherwise break nothing while still reading as plants, and a traceback naming
    no key is the one shape this module may not fail in.
    """
    stated = facts_for(path)
    if not stated:
        raise ConfigError(
            path,
            "states no alternation, so the fixtures that carry a member of it "
            "would carry nothing and the arms they assert would be asserted by "
            "nothing.",
        )
    return stated[0]


def _a_release_file(**overrides) -> dict:
    """§ 34's smallest valid version-carrying file, to break one key of at a time.

    ⛔ Built here rather than borrowed from whichever example carries the facet,
    for `_a_deploy_target`'s reason: a plant that broke one key of a shipped file
    would stop asserting the moment that file's list grew a second entry.
    ⚠️ The `regex` kind, because it is the one with keys of its own -- the
    `changelog` plants state the kind themselves.
    """
    entry = {
        "path": "a-file",
        "kind": "regex",
        "pattern": f"v(?P<{VERSION_CAPTURE}>1)",
        "replace": "v1",
    }
    entry.update(overrides)
    return {key: value for key, value in entry.items() if value is not _ABSENT}


def _a_release_of(**overrides) -> dict:
    """§ 34's smallest facet that carries a list, for the arms above the entries.

    ⛔ The carrier is `list` in every one of them: a plant that left it `none`
    would be refused by the stated-beside-an-absent-carrier arm instead, which is
    a different branch under a different key -- green while asserting nothing
    about the one it was aimed at.
    """
    facet = {
        "carrier": "list",
        "files": [_a_release_file()],
        "publishes_packages": False,
        "changelog_ci_owned": False,
    }
    facet.update(overrides)
    return {key: value for key, value in facet.items() if value is not _ABSENT}


def _a_verify_of(**overrides) -> dict:
    """§ 41's smallest facet that states a judgement, to break one key of at a time.

    ⛔ The carrier is `list` in every plant built on this, for `_a_release_of`'s
    reason: a plant that left it `none` would be refused by the
    stated-beside-an-absent-carrier arm instead -- a different branch under a
    different key, green while asserting nothing about the one it was aimed at.

    ⚠️ `identity` is keyed on `_a_deploy_target`'s own name, so a plant built on
    this has to be placed into a configuration carrying **that** target. The
    helper below is what does it, and nothing here reads a shipped example's
    target names: a fixture that did would stop asserting the moment the example
    it borrowed from renamed an environment.
    """
    facet = {
        "carrier": "list",
        "identity": {_a_deploy_target()["name"]: "a-command"},
        "baseline": {"ref": "a-ref", "harness": "/a/durable/path"},
        "breakpoints": [],
    }
    facet.update(overrides)
    return {key: value for key, value in facet.items() if value is not _ABSENT}


def _judging_one_target(**overrides) -> dict:
    """A complete example carrying one § 33 target and § 41's facet over it.

    ⛔ The target is replaced rather than appended to, which is what keeps the
    arms independent of whichever example `_a_valid_example` reads: a project
    whose own `deploy` list grew an entry would otherwise give the `identity`
    rules a second name to resolve against and the green arms would stop being
    about the mapping this fixture states.
    """
    data = _a_valid_example()
    data["deploy"] = [_a_deploy_target()]
    data["verify"] = _a_verify_of(**overrides)
    return data


def _a_document_row(**overrides) -> dict:
    """§ 38's smallest valid graph row, to break one key of at a time.

    ⛔ Built here rather than borrowed from whichever example carries the facet,
    for `_a_release_file`'s reason: a plant that broke one key of a shipped row
    would stop asserting the moment that file's graph grew a row.
    """
    row = {"document": "a-document.md", "may_name": [], "derived_from": []}
    row.update(overrides)
    return {key: value for key, value in row.items() if value is not _ABSENT}


def _a_documents_of(**overrides) -> dict:
    """§ 38's smallest facet that governs a document, for the arms above the rows.

    ⛔ The carrier is `list` in every one of them, for `_a_release_of`'s reason: a
    plant that left it `none` would be refused by the stated-beside-an-absent-
    carrier arm instead, which is a different branch under a different key --
    green while asserting nothing about the one it was aimed at.

    ⚠️ **One row and no edges**, so that every arm about an edge states its own:
    a fixture already carrying one would make an edge plant a *second* edge, and
    the refusal would then name an index the plant did not write.
    """
    facet = {
        "carrier": "list",
        "files": ["*.md"],
        "entry_points": ["a-document.md"],
        "graph": [_a_document_row()],
        "forbidden": [],
        "quoted": [],
    }
    facet.update(overrides)
    return {key: value for key, value in facet.items() if value is not _ABSENT}


def _a_spec_corpus_of(**overrides) -> dict:
    """§ 39's smallest facet that carries a corpus, for the arms above the globs.

    ⛔ The carrier is `repository` in every one of them, for `_a_documents_of`'s
    reason: a plant that left it `none` would be refused by the
    stated-beside-an-absent-carrier arm instead, which is a different branch
    under a different key -- green while asserting nothing about the one it was
    aimed at.

    ⚠️ **No `grouping` key**, because the example this is planted into carries
    § 4.8's single form: a fixture stating the name would be refused by the
    name-on-the-single-form arm before any glob arm could run, so each grouping
    plant states its own half instead.
    """
    facet = {
        "carrier": SPEC_CORPUS_REPOSITORY,
        "files": ["spec/**/*.md"],
        "load_bearing": [],
    }
    facet.update(overrides)
    return {key: value for key, value in facet.items() if value is not _ABSENT}


def _a_grouping_carrying_a_ref(name: str) -> dict:
    """One § 4.8 entry a ref is named after, for § 39's collection-form plants.

    ⛔ Every key § 4.8 requires of a carried grouping is stated, so a plant
    about *which* grouping a corpus names is not refused by a half-written entry
    first -- which is the way a plant certifies nothing while reading green.
    """
    return {
        "carrier": "native_milestone",
        "kind": "version",
        "current": "stated",
        "has_own_acceptance": False,
        "closes_items": False,
        "closed_by": "orderer",
        "ref_prefix": f"{name}/",
    }


def _two_groupings(data: dict, *, names=("one-scope", "another-scope")) -> dict:
    """`data` with § 4.8 written as a collection of two, both carrying a ref.

    ⛔ Written over the single form the example ships rather than beside it: the
    two forms are told apart by a `carrier` at the top, so a collection left
    with one would be read as the single form and the plant would land on an
    alternation instead of on § 39's which-grouping arm.
    """
    node = data.setdefault("work_item", {})
    node[ONE_GROUPING] = {name: _a_grouping_carrying_a_ref(name) for name in names}
    return data


def _a_box_diagrams(**overrides) -> dict:
    """§ 38's smallest stated diagram block, held and exempting nothing."""
    block = {"held": True, "exempt": []}
    block.update(overrides)
    return {key: value for key, value in block.items() if value is not _ABSENT}


def _a_diagram_exemption(**overrides) -> dict:
    """§ 38's smallest valid exemption, every key of which is stated."""
    entry = {
        "document": "a-document.md",
        "block": "a diagram drawn this way on purpose",
        "reason": "it reproduces a terminal's own output",
    }
    entry.update(overrides)
    return {key: value for key, value in entry.items() if value is not _ABSENT}


def _a_forbidden_name(**overrides) -> dict:
    """§ 38's smallest valid forbidding entry, every key of which is stated."""
    entry = {
        "pattern": "ALegacyName",
        "reason": "the component was deleted, so a document naming it describes nothing",
        "stable_because": "the name was removed rather than renamed",
    }
    entry.update(overrides)
    return {key: value for key, value in entry.items() if value is not _ABSENT}


def _a_billing_of(**overrides) -> dict:
    """§ 37's smallest facet that assembles a period, to break one key of at a time.

    ⛔ The carrier is `period` in every arm that uses this, for
    `_a_release_of`'s reason: a plant that left it `none` would be refused by
    the stated-beside-an-absent-carrier arm instead -- a different branch under
    a different key, green while asserting nothing about the one it was aimed
    at.

    ⛔ **And the root is absolute here**, which makes the fixture itself the
    green side of the one rule § 37 states in prose: the relative-root arm
    overrides this value, so that plant reddens on the thing it names rather
    than on a fixture that was never valid.
    """
    facet = {
        "carrier": "period",
        "projects": ["/a-project"],
        "rates": {"a-client": 1},
    }
    facet.update(overrides)
    return {key: value for key, value in facet.items() if value is not _ABSENT}


# The sentinel `_a_deploy_target` reads as *leave this key out*, which `None`
# cannot be: `None` is itself a value several arms refuse, and a fixture that
# used it would plant the wrong violation under the right key.
_ABSENT = object()


def _a_chat_kind_that_reads_an_archive() -> str:
    """A chat kind from the surface's own alternation that is not the absent one.

    ⛔ Read off the surface rather than spelled here, for the reason
    `_a_valid_example` is found rather than named: a fixture naming one chat
    implementation would be this code naming a vendor, which is the thing § 9's
    `kind` exists to stop the procedure doing.

    ⛔ A surface stating only the absent case is refused **with the key named**
    rather than left to raise out of the suite: the plants that use this would
    then break nothing while still reading as plants, and a traceback naming no
    key is the one shape this module may not fail in.
    """
    reads_one = [k for k in facts_for(CHAT_KIND_PATH) if k != NO_CHAT]
    if not reads_one:
        raise ConfigError(
            CHAT_KIND_PATH,
            "states no kind that reads an archive, so the plants that break the "
            "chat source would break nothing and the arms they assert would be "
            "asserted by nothing.",
        )
    return reads_one[0]


def _a_chat_stream_with_no_source(data: dict) -> dict:
    """The chat stream measured while its source says there is no chat at all."""
    _with(data, CHAT_KIND_PATH, NO_CHAT)
    streams = list(_absent_as(_get(data, STREAMS_PATH), []))
    if CHAT_STREAM not in streams:
        streams.append(CHAT_STREAM)
    return _with(data, STREAMS_PATH, streams)


def _a_chat_source_no_stream_reads(data: dict) -> dict:
    """An archive configured, addressed, and opened by no stream.

    ⚠️ The address goes in with the kind, or § 3's conditional marker refuses the
    missing `path` first and this arm is asserted by nothing.
    """
    _with(data, CHAT_KIND_PATH, _a_chat_kind_that_reads_an_archive())
    _with(data, f"{CHAT_BLOCK}.path", "<a planted archive>")
    streams = [s for s in _absent_as(_get(data, STREAMS_PATH), []) if s != CHAT_STREAM]
    return _with(data, STREAMS_PATH, streams)


def _example_meeting(on: str, value) -> dict | None:
    """The first example whose `on` holds `value`, or None where none does.

    Found rather than named, for the reason `_a_valid_example` is: a fixture this
    code pointed at one tracker would be the toolkit naming a tracker, and a kind
    whose block no example illustrates has to fail rather than quietly borrow
    another kind's file.
    """
    for path in _examples():
        with open(path, encoding="utf-8") as handle:
            data = _load_yaml(handle.read(), CONFIG_PATH)
        if isinstance(data, dict) and _get(data, on) == value:
            return data
    return None


def _without(data: dict, path: str) -> dict:
    """The same configuration with one key removed, parents left as they are."""
    node, parts = data, path.split(".")
    for part in parts[:-1]:
        node = node.get(part)
        if not isinstance(node, dict):
            return data
    node.pop(parts[-1], None)
    return data


def _with(data: dict, path: str, value) -> dict:
    """The same configuration with one key written back into it."""
    node, parts = data, path.split(".")
    for part in parts[:-1]:
        node = node.setdefault(part, {})
    node[parts[-1]] = value
    return data


def _said(data: dict) -> str:
    """What a refusal **said**, for the arms that share a key with a sibling.

    ⛔ **`_refused` answers the key and two arms can report the same one**, so a
    plant asserting the key alone passes with the arm it names deleted. ⚠️
    **Measured on § 37's blank root**: every whitespace-only string also fails
    the absoluteness test, so that plant stayed green with its own clause gone
    -- and the duplicate arm's two stated message properties, the written form
    of both entries, were asserted by nothing at all.
    """
    try:
        with open(SURFACE, encoding="utf-8") as handle:
            facts = surface_facts(handle.read())
        _resolve(data, EXAMPLES, facts, False)
    except ConfigError as error:
        return str(error)
    return ""


def _refused(data: dict, *, check_paths: bool = False, facts: dict | None = None) -> str | None:
    """The key a resolution refuses on, or None where it is accepted.

    `facts` is the surface to resolve against, for the one assertion that needs
    a surface other than this tree's: a refusal is the surface's only if it
    stops happening when the surface stops stating it.
    """
    if facts is None:
        with open(SURFACE, encoding="utf-8") as handle:
            facts = surface_facts(handle.read())
    try:
        _resolve(data, EXAMPLES, facts, check_paths)
    except ConfigError as error:
        return error.key
    return None


def _refusal_said(data: dict) -> str:
    """The whole of a refusal's text, or the empty string where none was raised.

    ⛔ Beside `_refused` above rather than widening it: that one answers which
    key a configuration is refused on, which is what every plant in this module
    compares, and an arm asserting what a *message* names is a different
    question. ⚠️ Two rules refusing on one key is exactly where it is worth
    asking -- the key is then no evidence about which of them fired.
    """
    with open(SURFACE, encoding="utf-8") as handle:
        facts = surface_facts(handle.read())
    try:
        _resolve(data, EXAMPLES, facts, False)
    except ConfigError as error:
        return str(error)
    return ""


def _example_missing(path: str, _loaded) -> str | None:
    data = _a_valid_example()
    node, parts = data, path.split(".")
    for part in parts[:-1]:
        node = node.get(part, {})
    node.pop(parts[-1], None)
    return _refused(data)


def _example_without(path: str, _loaded) -> str | None:
    """Remove an `absent_reason` from a facet whose carrier is `none`."""
    facet = path.rsplit(".", 1)[0]
    data = _a_valid_example()
    node, parts = data, facet.split(".")
    for part in parts:
        node = node.setdefault(part, {})
    node["carrier"] = "none"
    node.pop("absent_reason", None)
    return _refused(data)


# § 27's map, written for the run rather than shipped. ⛔ The one fixture class
# here that is built instead of found, and for the opposite reason to
# `_a_collection_example`'s: what this facet points at is somebody's identities,
# so a shipped fixture would be this repository holding a name -- which is the
# whole of what § 27 forbids. The roles and the identities below are words no
# tracker resolves, and the map lives in a directory the run deletes.
PLANTED_ROLE = "the role the work is for"
PLANTED_IDENTITY = "an-identity-no-tracker-resolves"
PLANTED_MAP_FILE = "a-role-to-person-map.yaml"


def _looked_up(role: str, mapping, *, key: str = "handle", written: bool = True,
               carrier: str = "file", source: str = PLANTED_MAP_FILE, **keys) -> str:
    """`identity <value>` where § 27's lookup answers, `stop <key>` where it does not.

    The map is written into a directory of its own and the configuration is
    resolved against that directory, because the pointer is relative to the
    skills root (§ 1).

    ⛔ Every arm reads the **whole** answer and not merely whether one came
    back: the failure § 27 exists against is a lookup that answers with the
    identity this session authenticates as, which is a successful-looking
    answer and not an error.
    """
    import tempfile  # noqa: PLC0415 -- one of the arms that needs a directory

    data = _a_valid_example()
    if carrier == "none":
        data[PEOPLE_KEY] = {
            "carrier": "none",
            "absent_reason": "one identity holds every role here",
        }
    else:
        data[PEOPLE_KEY] = dict(carrier="file", source=source, key=key, **keys)
    with open(SURFACE, encoding="utf-8") as handle:
        facts = surface_facts(handle.read())
    with tempfile.TemporaryDirectory() as root:
        if written:
            with open(os.path.join(root, source), "w", encoding="utf-8") as handle:
                handle.write(_yaml().safe_dump(mapping, allow_unicode=True))
        try:
            config = _resolve(data, root, facts, False)
            return f"identity {config.person_for(role)['identity']}"
        except ConfigError as error:
            return f"stop {error.key}"


# § 28's layer, written for the run rather than shipped, and for the reason
# § 27's map is: what the pointer addresses is the class of value this repository
# may not hold, so a shipped fixture would be the tree holding one. ⛔ The value
# below is a word no project uses, and the file lives in a directory the run
# deletes.
PLANTED_PRIVATE_FILE = "a-private-layer.yaml"
PLANTED_PRIVATE_VALUE = "a-value-this-repository-may-not-hold"


def _resolved_privately(listed, values, *, written: bool = True, read: str | None = None,
                        source: str = PLANTED_PRIVATE_FILE, carrier: str = PRIVATE_FILE,
                        valued: dict | None = None) -> str:
    """`value <v>` where § 28's read answers, `stop <key>` where it does not.

    The listed keys are cleared from the tracked configuration first, which is
    what a project moving its values out of review actually leaves behind;
    `valued` is how an arm writes one back, that being the collision the facet
    refuses.

    ⛔ Every arm reads the **value** and not merely whether a read succeeded. The
    failure § 28 exists against is a layer that resolves to nothing -- an empty
    list is a successful-looking answer, and a day measured from no chats at all
    is what it buys.
    """
    import tempfile  # noqa: PLC0415 -- the layer needs a directory of its own

    data = _a_valid_example()
    for path in listed:
        _with(data, path, None)
    for path, value in (valued or {}).items():
        _with(data, path, value)
    if carrier == PRIVATE_NONE:
        data[PRIVATE_KEY] = {
            "carrier": PRIVATE_NONE,
            "absent_reason": "every value this project states may be committed",
        }
    else:
        data[PRIVATE_KEY] = {
            "carrier": carrier,
            "source": source,
            "keys": list(listed),
        }
    with open(SURFACE, encoding="utf-8") as handle:
        facts = surface_facts(handle.read())
    with tempfile.TemporaryDirectory() as root:
        if written:
            with open(os.path.join(root, source), "w", encoding="utf-8") as handle:
                handle.write(_yaml().safe_dump(values, allow_unicode=True))
        try:
            configuration = _resolve(data, root, facts, False)
            return f"value {configuration.get(read or listed[0])!r}"
        except ConfigError as error:
            return f"stop {error.key}"


def _reported_privately(listed) -> dict:
    """What `to_dict` says about a project carrying § 28's layer.

    ⛔ Read off the report rather than asserted about the code: what this holds
    is that the key is named where it sits, that no value is anywhere in the
    output, and that the pointer and the list are stated once -- and the last of
    those is a property of the whole document rather than of any one key.
    """
    data = _a_valid_example()
    for path in listed:
        _with(data, path, None)
    data[PRIVATE_KEY] = {
        "carrier": PRIVATE_FILE,
        "source": PLANTED_PRIVATE_FILE,
        "keys": list(listed),
    }
    with open(SURFACE, encoding="utf-8") as handle:
        facts = surface_facts(handle.read())
    report = _resolve(data, EXAMPLES, facts, False).to_dict()
    rendered = json.dumps(report)
    return {
        "marked": all(
            str(_get(report["config"], path) or "").startswith("<private:")
            for path in listed
        ),
        "valued": PLANTED_PRIVATE_VALUE in rendered,
        "once": rendered.count(PLANTED_PRIVATE_FILE) == 1,
    }


def _refuses_missing_code_root() -> str | None:
    data = _a_valid_example()
    data["roots"]["code"] = "a-directory-that-does-not-exist"
    return _refused(data, check_paths=True)


# § 1's named roots. ⛔ The fixtures below are the **shipped** collection rather
# than a shape written here: a hand-built one would be a form this repository
# ships nowhere, and what the arms are for is that the form an adopter copies is
# the form that is held. Found rather than named, for the reason
# `_a_valid_example` is -- a fixture this code pointed at one tracker would be
# the toolkit naming a tracker.
def _a_target_stating(key: str) -> int:
    """The index of the first target in the shipped collection stating `key`.

    ⛔ Found by shape rather than written, which is every fixture here's rule:
    an index spelled out is one reordering away from planting on a target whose
    shape never reads the key, and a plant like that reddens on the shape rule
    instead -- green under a key that says nothing about what was asserted.
    """
    for index, entry in enumerate(
        _absent_as(_get(_a_collection_example() or {}, "deploy"), [])
    ):
        if isinstance(entry, dict) and entry.get(key):
            return index
    return -1


def _a_workflow_the_root_states(data: dict, key: str) -> str | None:
    """A workflow name the named root's own `host.checks` carries (§ 1, § 2)."""
    for check in _absent_as(_get(data, f"roots.code.{key}.host.checks"), []):
        if isinstance(check, dict) and isinstance(check.get("workflow"), str):
            return check["workflow"]
    return None


def _deploy_root_broken(index: int, **keys) -> str | None:
    """The key the shipped collection refuses on with one target's keys changed.

    ⚠️ The refusals the arms over this expect are all § 33's references into one
    repository, so the plant is written as *which root the target is in* as
    often as it is written as the reference: a reference nobody states would
    redden on its own does-anything-state-it arm, which asserts the opposite of
    the union being closed.
    """
    data = _a_collection_example()
    entry = _get(data, "deploy")[index]
    for key, value in keys.items():
        if value is _DROP:
            entry.pop(key, None)
        else:
            entry[key] = value
    return _refused(data)


def _keep_refusals_in(data: dict) -> dict:
    """Drop every § 31 refusal naming a target `data`'s own `deploy` no longer has.

    ⛔ For the fixtures that remove a target to reach a rule about something
    else: § 31's `refused_on` is resolved against § 33's names, so a target
    taken out from under a tier leaves a reference nothing carries and the
    configuration is refused for *that* instead of for what the fixture was
    built to exercise. ⚠️ It drops rather than rewrites: a tier refused on a
    target this project no longer deploys to is a tier refused on nothing, which
    is what the removal actually made true.
    """
    names = {
        entry.get("name")
        for entry in _absent_as(data.get("deploy"), [])
        if isinstance(entry, dict)
    }
    for tier in _absent_as(_get(data, "test_tiers.tiers"), []):
        if not isinstance(tier, dict) or "refused_on" not in tier:
            continue
        kept = [
            target for target in _absent_as(tier.get("refused_on"), [])
            if target in names
        ]
        if kept:
            tier["refused_on"] = kept
        else:
            tier.pop("refused_on")
    return data


def _a_collection_example() -> dict | None:
    for path in _examples():
        with open(path, encoding="utf-8") as handle:
            data = _load_yaml(handle.read(), CONFIG_PATH)
        if isinstance(data, dict) and isinstance(_get(data, "roots.code"), dict):
            return data
    return None


def _collection_keys() -> list[str]:
    data = _a_collection_example()
    return list(_get(data, "roots.code") or {}) if data else []


def _a_grouping_collection() -> dict | None:
    """The shipped example carrying § 4.8 as a block of named groupings.

    Found by shape rather than named, which is `_a_collection_example`'s rule
    one facet over: a fixture naming a tracker would be this code naming one.
    """
    for path in _examples():
        with open(path, encoding="utf-8") as handle:
            data = _load_yaml(handle.read(), CONFIG_PATH)
        stated = _get(data, GROUPING_KEY) if isinstance(data, dict) else None
        if isinstance(stated, dict) and "carrier" not in stated:
            return data
    return None


def _a_carried_grouping() -> dict | None:
    """The shipped example carrying § 4.8's single form with a real carrier.

    ⚠️ Found by the carrier being anything but `none`, so the arms below run
    against the shape an adopter copies rather than one built here -- and an
    example set that ships no carried single form fails those arms instead of
    having them quietly pass against the collection.
    """
    for path in _examples():
        with open(path, encoding="utf-8") as handle:
            data = _load_yaml(handle.read(), CONFIG_PATH)
        if not isinstance(data, dict):
            continue
        if _get(data, f"{GROUPING_KEY}.carrier") not in (None, "none"):
            return data
    return None


def _grouping_stop(data: dict) -> str:
    """The whole refusal § 4.8's lookup gives for an unnamed one of several.

    ⛔ The message rather than the key, because the arm that reads it asserts the
    groupings are **named in it**: a stop that says only *several* leaves whoever
    reads it no further forward than before it fired.
    """
    try:
        with open(SURFACE, encoding="utf-8") as handle:
            _resolve(data, EXAMPLES, surface_facts(handle.read()), False).grouping()
    except ConfigError as error:
        return str(error)
    return "the lookup answered rather than stopping"


def _grouping_or_refused(data: dict, name: str | None = None) -> str:
    """`grouping <name>` where § 4.8's lookup answers, `stop <key>` where not."""
    if not data:
        return "no example carries the shape this fixture is built from"
    with open(SURFACE, encoding="utf-8") as handle:
        facts = surface_facts(handle.read())
    try:
        resolved = _resolve(data, EXAMPLES, facts, False).grouping(name)
    except ConfigError as error:
        return f"stop {error.key}"
    return f"grouping {resolved['name']}"


def _collection_broken(mutate) -> str | None:
    """The key a collection with one plant in it refuses on."""
    data = _a_collection_example()
    mutate(_get(data, "roots.code"))
    return _refused(data)


# § 1's command roots. ⛔ The **shipped** collection again, for the reason stated
# above it: what an adopter copies is what is held, and a hand-built block would
# be a shape this repository ships nowhere. ⚠️ Which root carries the facet is
# found by shape rather than named, so an example that moves it is still held.
def _a_command_root_root() -> str:
    """The key of the code root the shipped collection declares command roots on."""
    for key, entry in (_get(_a_collection_example() or {}, "roots.code") or {}).items():
        if isinstance(entry, dict) and entry.get(COMMAND_ROOTS):
            return key
    return ""


def _a_plain_code_root() -> str:
    """The key of the code root that declares none, which is the facet's green side."""
    for key, entry in (_get(_a_collection_example() or {}, "roots.code") or {}).items():
        if isinstance(entry, dict) and not entry.get(COMMAND_ROOTS):
            return key
    return ""


def _command_root_broken(mutate, *, check_paths: bool = False) -> str | None:
    """The key a collection with one plant in its command roots refuses on.

    `mutate` is handed the **entry** that declares them, so a plant reaches both
    the block and the `host.checks` beside it -- the two halves § 1 states, the
    roots and the reference into them.
    """
    data = _a_collection_example()
    mutate(_get(data, f"roots.code.{_a_command_root_root()}"))
    return _refused(data, check_paths=check_paths)


def _a_single_form_with_command_roots() -> dict:
    """A single-root example carrying § 1's command roots at the top level.

    ⛔ The one place a command-root fixture is built rather than shipped, and the
    reason is § 4.7's built fixture's: the shipped collection can only carry the
    facet *inside* an entry, so the single form's own spelling -- the block at the
    top level beside `host` and `branch_model`, which is where every per-root
    block of a single-root project is written -- would be exercised by nothing.
    ⚠️ The block is **lifted off the shipped collection** rather than written
    here, so what is held is still the shape an adopter copies.
    """
    data = _a_valid_example()
    source = _get(_a_collection_example(), f"roots.code.{_a_command_root_root()}")
    data[COMMAND_ROOTS] = copy.deepcopy(source[COMMAND_ROOTS])
    return data


def _a_collection_carrying(carrier: str, mapping: dict, **keys) -> dict:
    """The shipped collection with § 4.7's facet carried another way.

    ⛔ The one place a § 4.7 fixture is built rather than shipped, and the reason
    is the shipped collection can carry one carrier at a time: the two it does
    not carry are the two whose matching rules differ from it, so arms over the
    shipped file alone leave `_opens_with` and the one-value rule unexercised.
    ⚠️ The roots are the shipped collection's own, so the mapping is still held
    to the keys a project actually has.
    """
    data = _a_collection_example()
    facet = _get(data, "work_item.code_root")
    facet.clear()
    facet.update(carrier=carrier, roots=mapping, **keys)
    return data


def _resolved_or_refused(data: dict, values: list[str]) -> str:
    """`root <slug>` where § 4.7's resolution answers, `stop <key>` where it does not."""
    with open(SURFACE, encoding="utf-8") as handle:
        facts = surface_facts(handle.read())
    try:
        config = _resolve(data, EXAMPLES, facts, False)
    except ConfigError as error:
        return f"refused {error.key}"
    try:
        return f"root {config.root_for(values).root_key}"
    except ConfigError as error:
        return f"stop {error.key}"


def _project_read(configuration: Config, path: str) -> str | None:
    """The message a project-level read of a per-root fact is refused with.

    `None` where the read answered, which is what the complement arm asserts.
    `mirrors` names the accessor rather than a key: the two reach one refusal,
    the accessor asking for the key before it walks the facet.
    """
    try:
        if path == "mirrors":
            configuration.mirrors()
        else:
            configuration.get(path)
    except ConfigError as error:
        return str(error)
    return None


def _a_valid_example_with(path: str, value) -> dict:
    """A complete example with one key written back into it."""
    return _with(_a_valid_example(), path, value)


def _place(data: dict, path: str, value) -> str:
    """Write `value` at `path`, descending into the first entry of any list.

    Returns the path the configuration now carries it at, which is the dotted
    one with an index wherever a list was crossed. ⛔ The index is why this
    exists: a retired key declared inside a list member -- § 13's entries are
    list members -- cannot be written at the surface's own spelling of its path,
    and a plant that silently created a *dict* called `done` instead would
    redden on the shape rule rather than on the retirement it was written for.
    """
    node, parts, at = data, path.split("."), []
    for part in parts[:-1]:
        if isinstance(node, list):
            if not node:
                node.append({})
            at.append("[0]")
            node = node[0]
        node = node.setdefault(part, {})
        at.append(f".{part}" if at else part)
    if isinstance(node, list):
        if not node:
            node.append({})
        at.append("[0]")
        node = node[0]
    node[parts[-1]] = value
    at.append(f".{parts[-1]}" if at else parts[-1])
    return "".join(at)


def _refuses_a_root_with_no_config() -> tuple[str | None, bool]:
    """(the key the refusal names, whether it also names the root it looked in).

    The examples directory is a root with no configuration in it, so no
    temporary tree is needed to reach this branch.
    """
    root = EXAMPLES
    try:
        load(root)
    except ConfigError as error:
        return error.key, os.path.abspath(root) in str(error)
    return None, False


# --- entry point -----------------------------------------------------------


def main(argv: list[str]) -> int:
    parser = argparse.ArgumentParser(
        description="Read a project's configuration, once, for every role.",
    )
    parser.add_argument(
        "--skills-root",
        default=".",
        help="the root the configuration is resolved relative to. Defaults to the "
        "working directory, which § 1 states is the skills root; pass it to "
        "address a project the role is not standing in",
    )
    parser.add_argument(
        "--no-check-paths",
        action="store_true",
        help="resolve without testing that the configured code root exists",
    )
    named = parser.add_mutually_exclusive_group()
    named.add_argument(
        "--root",
        help="the named code root to resolve, where § 1's collection carries "
        "several. Omitted, the whole configuration is reported and a fact "
        "stated per root is reported per root",
    )
    named.add_argument(
        "--root-for",
        nargs="+",
        metavar="VALUE",
        help="what the item carries on § 4.7's carrier -- every label on it, the "
        "named field's value, or its title -- resolved to the one root it "
        "names. A root named by none of them, or by two, is a stop",
    )
    parser.add_argument(
        "--person-for",
        metavar="ROLE",
        help="the role whose holder to look up in § 27's map, printed with the "
        "pointer and the key it was read through. Every failure is a stop: a "
        "project with no map, an unreadable pointer and a role the map does not "
        "name are each reported, and none of them answers with whoever is "
        "running this",
    )
    parser.add_argument(
        "--exempt-for",
        nargs="+",
        metavar="PATH",
        help="the change's own files, repository-relative, held against § 30's "
        "classes. Prints the verdict, every class that matched, the branch an "
        "exempt change is committed to and the paths that fell outside every "
        "class. ⛔ No count of anything is read: a change wholly inside a class "
        "is exempt at one line and at two hundred files alike",
    )
    parser.add_argument(
        "--of-kind",
        metavar="KIND",
        help="what the change is, for a § 30 class that states `kinds`. Omitted, "
        "a class that states them is left unanswered rather than defaulted either "
        "way, and `loop_exempt.borderline` says who answers it",
    )
    parser.add_argument(
        "--command",
        metavar="COMMAND",
        help="a command to resolve against § 1's command roots. Prints what to "
        "run, the directory to run it in, and whether that directory is there -- "
        "⛔ a root reached through an `invoke` form alone is reported "
        "unestablished rather than absent, and a role that cannot reach it names "
        "the root rather than running at the code root",
    )
    parser.add_argument(
        "--command-root",
        metavar="NAME",
        help="which of § 1's command roots `--command` runs in. Omitted, the "
        "command runs at the code root -- and a code root stating "
        f"`{CODE_ROOT_RUNS_NOTHING}: true` makes that omission a stop rather "
        "than an answer",
    )
    parser.add_argument(
        "--deploy-target",
        metavar="TARGET",
        help="one of § 33's deploy targets, resolved as a run would invoke it: the "
        "command and where it runs, or the workflow, the ref and every input, with "
        "each choice, the value taken and any warning declared for it",
    )
    parser.add_argument(
        "--choose",
        action="append",
        metavar="NAME=VALUE",
        help="a value for one of that target's choices, repeated per choice and per "
        "value where a choice may take several. One the target does not allow is a "
        "stop. A choice left out takes its default",
    )
    parser.add_argument(
        "--tier",
        metavar="TIER",
        help="the § 31 tier to report: every suite classified under it, what each "
        "needs, who stands its dependency up, whether it starts itself, the "
        "criterion its cases are chosen by and whether anything holds that "
        "criterion, the targets it is refused on, and where its verdict comes "
        "from. ⛔ A suite stating no source is reported as **no answer** and "
        "never as green, and a tier the project does not state is reported as a "
        "tier with nothing to lack rather than as one that passed",
    )
    parser.add_argument(
        "--against-target",
        metavar="TARGET",
        help="one of § 33's deploy targets, by the name that facet keys it on: "
        "every suite `--tier` reports comes back with whether this target "
        "refuses it, which is the reading the reviewing role performs its § 31 "
        "refusal on. ⛔ A name no `deploy` entry states is a stop and never an "
        "answer of not-refused",
    )
    parser.add_argument(
        "--self-test",
        action="store_true",
        help="hold this reader to the surface and the examples",
    )
    args = parser.parse_args(argv)

    if args.self_test:
        print("Holding the reader to the surface and the examples:")
        return self_test()

    try:
        config = load(args.skills_root, check_paths=not args.no_check_paths)
        if args.root:
            config = config.root(args.root)
        elif args.root_for:
            config = config.root_for(args.root_for)
        # ⛔ After the root narrowing and not instead of it: § 27's map is the
        # project's rather than a root's, so either form resolves it, and a role
        # that has narrowed to a root still asks the same question.
        answer = config.person_for(args.person_for) if args.person_for else None
        # ⛔ After the root narrowing for § 27's reason one argument up: § 31's
        # facet is the project's rather than a root's, so either form resolves
        # it and a role that has narrowed to a root asks the same question.
        if args.tier:
            answer = config.tier(args.tier, args.against_target)
        elif args.against_target:
            raise ConfigError(
                "test_tiers.tiers.refused_on",
                "cannot be asked about a target with no tier named: § 31 states "
                "the refusal per suite, so a target alone asks which of nothing "
                "is refused. Pass `--tier` with it, or read the targets this "
                "project states out of the report this run prints without either.",
            )
        # ⛔ After the root narrowing for § 27's reason, and ⚠️ **the kind is
        # read whether or not it was given**: a run that passed paths and no
        # kind is asking the question § 30's third verdict answers, so dropping
        # the argument would turn an unanswered class into a silent *not
        # exempt* -- the safe-looking reading that drops the exemption a project
        # configured.
        # ⛔ After the root narrowing, and that is the facet's own rule rather
        # than this parser's order: § 1's command roots belong to one code root,
        # so a project with several resolves the code root first and a read made
        # at the project level is refused by `get` rather than answered from the
        # first of them.
        if args.command:
            answer = config.command(args.command, args.command_root)
        elif args.command_root:
            raise ConfigError(
                COMMAND_ROOT_REF,
                "names a root with no command to run in it: § 1 states the root "
                "a *command* runs in, so a name alone asks nothing. Pass "
                "`--command` with it, or read the roots this project declares "
                "out of the report this run prints without either.",
            )
        if args.deploy_target:
            # ⛔ The repository is the entry's own fact, so a root handed over
            # beside the target is a second answer to it.
            if args.root or args.root_for:
                raise ConfigError(
                    f"deploy.{DEPLOY_CODE_ROOT}",
                    "is the target's own statement of its repository (§ 33), so a "
                    "root is not passed beside `--deploy-target`.",
                )
            if args.command:
                raise ConfigError(
                    "deploy.command",
                    "is the target's own statement of what it runs (§ 33), so a "
                    "command is not passed beside `--deploy-target`.",
                )
            answer = config.deploy_target(args.deploy_target, args.choose)
        elif args.choose:
            raise ConfigError(
                "deploy.choices",
                "cannot be chosen with no target named: § 33 states a choice per "
                "target. Pass `--deploy-target` with it.",
            )
        if args.exempt_for:
            answer = config.exempt_for(args.exempt_for, args.of_kind)
        elif args.of_kind:
            raise ConfigError(
                EXEMPT_CLASSES_PATH,
                "cannot be asked about a kind with no changed path: § 30 holds a "
                "class's `paths` against every file a change touches, so `--of-kind` "
                "alone would answer about a change this run cannot see. Pass "
                "`--exempt-for` with the change's files.",
            )
    except ConfigError as error:
        print(str(error), file=sys.stderr)
        return 1
    if answer is not None:
        print(json.dumps(answer, indent=2, ensure_ascii=False, sort_keys=False))
        return 0
    print(json.dumps(config.to_dict(), indent=2, ensure_ascii=False, sort_keys=False))
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))
